<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class QuoteOffer extends Model{use HasUuids;protected$fillable=['quote_id','carrier_id','product_id','tariff_version_id','premium_minor','tax_minor','fee_minor','total_minor','currency','status','calculation_breakdown','valid_until','decline_reason_code','coverage_snapshot','external_reference','comparison_rank','ranking_reasons','sellability','original_premium_minor','original_total_minor','premium_override_id'];protected function casts():array{return['calculation_breakdown'=>'array','coverage_snapshot'=>'array','valid_until'=>'datetime','ranking_reasons'=>'array','sellability'=>'array'];}public function quote():BelongsTo{return$this->belongsTo(Quote::class);}public function product():BelongsTo{return$this->belongsTo(InsuranceProduct::class,'product_id');}public function carrier():BelongsTo{return$this->belongsTo(Carrier::class);}public function tariff():BelongsTo{return$this->belongsTo(TariffVersion::class,'tariff_version_id');}}
